    text = f.read()
# Look for releases in the JSON payload
scripts = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', text, re.DOTALL)
for i, s in enumerate(scripts):
    if len(s) > 1000 and 'release' in s.lower():
        try:
            data = json.loads(s)
            if 'payload' in data and 'preloadedQueries' in data['payload']:
                for q in data['payload']['preloadedQueries']:
                    if 'result' in q and 'data' in q['result']:
                        repo = q['result']['data'].get('repository', {})
                        if 'releases' in repo:
                            print('Found releases in script', i)
                            releases = repo['releases']
                            print('releases keys:', list(releases.keys()))
                            if 'nodes' in releases:
                                print('nodes:', len(releases['nodes']))
                                for r in releases['nodes'][:3]:
                                    print(r)
                        if 'search' in repo:
                            print('Found search in script', i)
                            search = repo['search']
                            print('search keys:', list(search.keys()))
                            if 'issueCount' in search:
                                print('issueCount:', search['issueCount'])
        except Exception as e:
            pass

# Look for specific text patterns indicating no releases
no_release_matches = re.findall(r'There are no releases|No releases published|No releases yet|No releases', text, re.IGNORECASE)
print('No release text matches:', no_release_matches)
